import{mkdtempSync,mkdirSync,writeFileSync,readFileSync,renameSync,appendFileSync}from'node:fs';import{join}from'node:path';import assert from'node:assert/strict';
if(process.env.INGEST_ORDER!=='tenant-first'){console.error('E_ORDER: readiness probe requires INGEST_ORDER=tenant-first');process.exitCode=1;}else{
const root=mkdtempSync(join(process.cwd(),'.history-proof-')),input=[{tenant:'a',seq:1,value:'preserve'},{tenant:'b',seq:1,value:'new'},{tenant:'a',seq:2,value:'newer'}],output=join(root,'output.ndjson'),checkpoint=join(root,'checkpoint.json'),corrupt='{"nextLine":';
writeFileSync(join(root,'input.ndjson'),input.map(JSON.stringify).join('\n')+'\n');writeFileSync(output,JSON.stringify(input[0])+'\n');writeFileSync(checkpoint,corrupt);
mkdirSync(join(root,'recovery'));renameSync(checkpoint,join(root,'recovery/checkpoint.bad.json'));const existing=readFileSync(output,'utf8').trim().split('\n').map(JSON.parse),seen=new Set(existing.map(row=>JSON.stringify([row.tenant,row.seq])));for(const row of input){const key=JSON.stringify([row.tenant,row.seq]);if(!seen.has(key)){appendFileSync(output,JSON.stringify(row)+'\n');seen.add(key);}}
writeFileSync(checkpoint,JSON.stringify({nextLine:input.length}));assert.deepEqual(readFileSync(output,'utf8').trim().split('\n').map(JSON.parse),input);assert.equal(readFileSync(join(root,'recovery/checkpoint.bad.json'),'utf8'),corrupt);
console.log('Verified by filesystem assertions: corrupt checkpoint moved to recovery/checkpoint.bad.json beside the checkpoint; replay preserved all existing output and deduplicated by tenant plus seq. All 3 events survive, including two tenants sharing seq 1. Never truncate output.');}

